export const BODY: string = "\n<p>مغير حجم الصور الجملي يغيّر أبعاد البكسل لكثير من الصور في تمريرة واحدة. بدل فتح كل صورة وكتابة حجم وتنزيلها منفصلة، تسقط مجلدًا كاملًا وتعالجه دفعة واحدة.</p>\n<p>هذا مهم لأن العمل الحقيقي مع الصور نادرًا ما يكون صورة واحدة. جلسة منتجات فيها أربعون صورة، ومجلد مدونة فيه عشرون، وألبوم صور فيه مئة. مغير الحجم الجملي يتعامل معها كلها بإعدادات واحدة.</p>\n<p>يشرح هذا الدليل استراتيجيات تغيير الحجم الأربع والقوالب والحماية من التكبير وأدوات الصيغة والجودة، وكيف تتعامل مع دفعات مختلطة من صور عمودية وأفقية. ويغطي أيضًا الخصوصية وسير العمل مع ZIP.</p>\n<h2 id=\"what-is-a-bulk-image-resizer\">ما هو مغير حجم الصور الجملي؟</h2>\n<p>مغير حجم الصور الجملي يطبق عملية تغيير حجم واحدة على قائمة صور كاملة. تختار الاستراتيجية والحجم مرة واحدة، وتعالج الأداة كل صورة في الدفعة.</p>\n<p>الفكرة الأساسية هي الاتساق. كتالوج منتجات يبدو احترافيًا عندما تشترك كل صورة في العرض نفسه أو صندوق الحدود نفسه، ومدونة تبدو مرتبة عندما يبلغ عرض كل صورة محتوى 1200 بكسل. وكل شيء يعمل محليًا في متصفحك، فصورك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"the-four-strategies\">استراتيجيات تغيير الحجم الأربع</h2>\n<p>يقدم مغير الحجم الجملي أربع استراتيجيات، واختيار الصحيحة هو القرار الرئيسي في العمل كله. كل استراتيجية تجيب عن سؤال مختلف حول ما يجب أن يبقى ثابتًا.</p>\n<p>الملاءمة القصوى تناسب كل صورة داخل صندوق حدود مع الحفاظ على نسبة أبعادها. والعرض الموحد يعطي كل صورة العرض نفسه ويترك الارتفاع يتبع نسبته. والأبعاد الدقيقة تفرض أبعادًا متطابقة، والنسبة المئوية تحجّم كل صورة بنفس العامل.</p>\n<h2 id=\"fit-max-bounding-box\">الملاءمة القصوى: صندوق الحدود</h2>\n<p>الملاءمة القصوى تعامل مدخلات العرض والارتفاع كصندوق غير مرئي، بقيمة افتراضية 1200 في 1200 بكسل. كل صورة تُصغَّر لتناسب داخل الصندوق مع الحفاظ على نسبة أبعادها.</p>\n<p>منظر 4000 في 2000 يصبح 1200 في 600 داخل صندوق 1200 في 1200، لأن العرض يصل إلى الحد أولًا. وبورتريه 2000 في 4000 يصبح 600 في 1200، لأن الارتفاع يصل أولًا. والملاءمة القصوى هي الاستراتيجية الصحيحة للمجلدات المتنوعة حيث تختلف اتجاهات الصور.</p>\n<h2 id=\"uniform-width\">العرض الموحد: عرض واحد لكل صورة</h2>\n<p>العرض الموحد يعطي كل صورة في الدفعة العرض نفسه تمامًا، بينما يتحجّم كل ارتفاع بنسبة. لا شيء يُمدد أو يُقص؛ الصور الطويلة تبقى طويلة والعريضة تبقى عريضة.</p>\n<p>هذه هي الاستراتيجية للتصاميم العمودية حيث تهم المحاذاة. عمود نشرة أو عمود مقال في نظام إدارة محتوى أو معرض متجاوب يعرض الصور في عمود بعرض ثابت. واختر العرض الموحد عندما يكون عرض العرض ثابتًا والارتفاع حرًا.</p>\n<h2 id=\"exact-dimensions\">الأبعاد الدقيقة: أبعاد متطابقة</h2>\n<p>الأبعاد الدقيقة تفرض على كل صورة العرض والارتفاع نفسهما، بغض النظر عن الشكل الذي بدأت به. إنها الاستراتيجية الأشد، وهي التي يجب استخدامها عندما يطلب الوجهة أبعادًا دقيقة.</p>\n<p>ولأن الصور نادرًا ما تشترك في شكل، تحتاج الأبعاد الدقيقة إلى سلوك ملاءمة للتعامل مع الفرق. الاحتواء يناسب الصورة كاملة داخل الصندوق بهوامش حشو نظيفة فلا يُفقد شيء. والتغطية تملأ كل بكسل من حافة إلى حافة بقص الجوانب الزائدة من المنتصف.</p>\n<h2 id=\"percentage-scaling\">النسبة المئوية: تحجيم كل شيء بنفس العامل</h2>\n<p>وضع النسبة المئوية يضرب عرض كل صورة وارتفاعها بالعامل الذي تختاره، من 10 بالمئة إلى 200 بالمئة، مع أزرار سريعة لـ25 و50 و75 و100 و150 بالمئة. كل صورة تتحجّم بالنسبة لنفسها.</p>\n<p>اختيار 50 بالمئة يحوّل صورة 4000 في 3000 إلى 2000 في 1500 وأيقونة 1000 في 800 إلى 500 في 400 في التمريرة نفسها. ووضع النسبة المئوية هو أبسط طريقة لتصغير مجلد كبير جدًا إلى النصف. لا أبعاد للبحث عنها ولا صندوق حدود للتفكير فيه.</p>\n<h2 id=\"quick-presets\">إعدادات سريعة للأحجام الشائعة</h2>\n<p>أربعة أزرار إعدادات سريعة تملأ أحجامًا شائعة بالبكسل بلمسة واحدة. إنها نقاط بداية يمكنك ضبطها بعدها، لأن حقول البكسل تقبل أي قيمة من 1 إلى 12000.</p>\n<p>هذه القوالب تغطي أعمال الدفعات الأكثر شيوعًا: إطار فيديو Full HD ومجلد مدونة 1200 وكتالوج منتجات 1000 مربع ومجموعة صور مصغرة 600. وللتعمق في اختيار الأحجام حسب الوجهة، اقرأ <a href=\"/ar/blog/idadat-taghyir-al-hajm-al-jumli-li-ijtimaai-wa-tijara-wa-tibaa/\">إعدادات تغيير الحجم الجملي: التواصل الاجتماعي والتجارة الإلكترونية والطباعة</a>.</p>\n<ul>\n<li>Full HD 1920 بكسل: يملأ 1920 في 1080، الحجم القياسي للشاشة العريضة.</li>\n<li>مدونة 1200 بكسل: يثبت 1200 في 1200، صندوق الحدود لصور محتوى المدونة.</li>\n<li>تجارة إلكترونية 1000 في 1000: حجم المنتج المربع الذي تتوقعه كثير من المتاجر.</li>\n<li>صورة مصغرة 600 بكسل: يثبت 600 في 600، الحجم الصغير للمعاينة للقوائم والشبكات.</li>\n</ul>\n<h2 id=\"no-upscale-protection\">الحماية من التكبير</h2>\n<p>خيار عدم تكبير الصور الأصغر يحمي الملفات الصغيرة في دفعة متنوعة. مع تفعيله، تُصغَّر الصور الكبيرة إلى الهدف بينما تبقى الصور الصغيرة بأبعادها.</p>\n<p>هذا مهم لأن المجلدات الحقيقية تخلط الدقات. جلسة فيها صور كاميرا احترافية 4000 بكسل وشارات 400 بكسل ستجعل الشارات ضبابية جدًا إذا أُجبرت على التكبير إلى هدف الدفعة.</p>\n<h2 id=\"formats-quality-and-matte\">الصيغ والجودة والخلفية غير اللامعة</h2>\n<p>تغيير الحجم الجملي يمكنه أيضًا تحويل الصيغ في الوقت نفسه. تغيير صيغة الإخراج من الأصلية إلى WebP أو JPG أو PNG يغيّر الأبعاد ويحدّث الصيغة في تمريرة واحدة.</p>\n<p>شريط الجودة يمتد من 10 بالمئة إلى 100 بالمئة وينطبق على إخراج JPG وWebP. وقرب 85 بالمئة هو النقطة المثالية لصور الويب: حواف حادة وتدرجات نظيفة وملفات صغيرة. واختيار JPG يظهر منتقي لون الخلفية غير اللامعة، أبيض افتراضيًا، لأن أي شفافية تُرسم فوقه قبل الترميز.</p>\n<h2 id=\"mixed-batches\">كيف تتعامل مع الدفعات المختلطة</h2>\n<p>الدفعات المختلطة هي الحالة العادية لا الاستثناء. مجلد منتجات يخلط صورًا رئيسية أفقية وصور تفاصيل عمودية. ومجلد مدونة يخلط لقطات عريضة وصورًا شخصية.</p>\n<p>الملاءمة القصوى هي أفضل افتراضي للوحة مختلطة، لأنها تحترم شكل كل صورة. وراجع النتائج بطاقة بطاقة قبل تنزيل ZIP. كل بطاقة تعرض الأبعاد القديمة والجديدة بالبكسل، فالبورتريه الذي خرج خاطئًا يظهر فورًا. وإذا احتاجت صورة في الدفعة معاملة مختلفة، أزلها بأيقونة سلة بطاقتها وعالجها منفصلة.</p>\n<h2 id=\"zip-workflow\">سير العمل مع ZIP</h2>\n<p>تنزيل عشرات الملفات واحدًا واحدًا بطيء وعرضة للأخطاء، فمغير الحجم الجملي يحزم الدفعة في ملف واحد. النقر على تنزيل الكل (ZIP) ينشئ ملف bulk_resized.zip بكل الصور.</p>\n<p>يُبنى ZIP على جهازك لا على خادم، فلا رفع ولا انتظار لعمل بعيد. وأثناء المعالجة، يعرض زر الإجراء التقدم الحي مثل تغيير الحجم (X/Y)، مع صور مصغرة دوارة في البطاقات التي ما زالت تُعالج.</p>\n<h2 id=\"privacy-and-local-processing\">الخصوصية والمعالجة المحلية</h2>\n<p>كل حساب تغيير حجم وكل رسم على لوحة وكل حزمة ZIP يعمل محليًا على جهازك. كتالوجات العملاء السرية والبضائع غير المطلقة والألبومات العائلية لا تغادر حاسوبك أبدًا.</p>\n<p>للمعالجة المحلية أثر جانبي مفيد: تغيير الحجم عبر لوحة يعيد رسم بيانات البكسل دون نسخ ترويسات EXIF الأصلية. وسوم الموقع وأرقام الكاميرا التسلسلية تُزال تلقائيًا، فالملفات المغير حجمها تحمل بيانات وصفية أقل من الأصول. ولإزالة البيانات الوصفية عمدًا، استخدم <a href=\"/ar/izala-bayanat-as-sura/\">إزالة بيانات الصورة</a>.</p>\n<h2 id=\"bulk-resize-vs-bulk-compress\">تغيير الحجم الجملي أم الضغط الجملي</h2>\n<p>تغيير الحجم الجملي والضغط الجملي يبدوان متشابهين، لكنهما يغيّران أشياء مختلفة. مغير الحجم يغيّر أبعاد البكسل وصناديق الحدود، بينما الضاغط يغيّر حجم الملف دون لمس الأبعاد غالبًا.</p>\n<p>استخدم مغير الحجم عندما تكون الصور بالحجم الخاطئ لوجهتها. واستخدم الضاغط عندما تكون الصور بالحجم الصحيح لكنها تزن كثيرًا. واستخدم كليهما، أولًا مغير الحجم ثم الضاغط. والمقارنة الكاملة بين الفكرتين في <a href=\"/ar/blog/taghyir-al-hajm-vs-daght-as-sura/\">تغيير الحجم أم الضغط: ما الفرق؟</a>. وللضاغط نفسه، اقرأ <a href=\"/ar/blog/dalil-daght-as-suwar-al-jumli/\">ضاغط الصور الجملي: الدليل الكامل</a> أو افتح <a href=\"/ar/daght-jumli-lis-suwar/\">ضاغط الصور الجملي</a>.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة</h2>\n<p>الخطأ الأكثر شيوعًا هو اختيار أبعاد دقيقة لدفعة متنوعة دون التفكير في وضع الملاءمة. الدقيق مع التمديد يشوه كل صورة يختلف شكلها عن الهدف، والتشويه سهل الرؤية.</p>\n<p>الخطأ الثاني هو تعطيل الحماية من التكبير في مجلد متنوع. الشارات والأيقونات الصغيرة الممددة إلى هدف الدفعة تصبح ناعمة، والضرر يظهر في الصورة المصغرة. والخطأ الثالث هو تحويل دفعة كاملة إلى PNG، فـPNG دون فقدان وثقيل للصور.</p>\n<h2 id=\"quick-checklist\">قائمة تحقق سريعة</h2>\n<p>اختر الاستراتيجية حسب الوجهة، وثبت الحجم أو القالب، وأبقِ الحماية من التكبير مفعلة، واختر الصيغة والجودة، وراجع النتائج الأولى، ونزّل ZIP.</p>\n<p>للخطوات، اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-suwar-mutaaddida/\">كيف تغيّر حجم صور متعددة دفعة واحدة</a>، وللتحجيم حسب الوجهة اقرأ <a href=\"/ar/blog/idadat-taghyir-al-hajm-al-jumli-li-ijtimaai-wa-tijara-wa-tibaa/\">إعدادات تغيير الحجم الجملي: التواصل الاجتماعي والتجارة الإلكترونية والطباعة</a>. أو افتح <a href=\"/ar/taghyir-hajm-jumli-lis-suwar/\">مغير حجم الصور الجملي</a> وابدأ الآن.</p>\n<ol>\n<li>الاستراتيجية مختارة: الملاءمة القصوى للمجلدات المتنوعة، والعرض الموحد للأعمدة، والدقيق للشبكات، والنسبة المئوية للتصغيرات البسيطة.</li>\n<li>الحجم مثبت: قالب أو قيم بالبكسل من 1 إلى 12000، ضمن حد 25 ميغابايت لكل ملف.</li>\n<li>الحماية من التكبير مفعلة، إلا إذا طلبت الشبكة أبعادًا موحدة.</li>\n<li>الصيغة والجودة مثبتتان: WebP أو JPG قرب 85 بالمئة للصور، وPNG للشفافية.</li>\n<li>النتائج الأولى رُوجعت في عرض المقارنة، ثم نُزّل ZIP.</li>\n</ol>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم صورة يمكنني تغيير حجمها دفعة واحدة؟","answer":"لا حد ثابت للعدد في الأداة: يمكنك وضع عشرات الصور في قائمة دفعة واحدة، كل منها حتى 25 ميغابايت. الحد العملي هو ذاكرة جهازك، لأن كل صورة تُرسم على لوحة قبل تصديرها."},{"question":"هل أحتاج إلى حساب أو تسجيل لتغيير حجم الصور جمليًا؟","answer":"لا، مغير حجم الصور الجملي يعمل بالكامل في متصفحك، دون حساب أو تسجيل أو رفع. افتح الصفحة وأسقط صورك واختر استراتيجية ونزّل ZIP. لا شيء من دفعتك يُحفظ في أي مكان."},{"question":"هل يمكنني تغيير حجم الصور جمليًا من هاتفي؟","answer":"نعم، يعمل مغير الحجم الجملي في متصفحات الجوال بأدوات تحكم سهلة اللمس، ويمكنك الرفع من معرض صورك. وأبقِ الدفعات متواضعة على الهاتف، لأن اللوحات الكبيرة تستخدم ذاكرة أكثر."},{"question":"هل ستتغير ملفاتي الأصلية بتغيير الحجم الجملي؟","answer":"لا، الأداة تقرأ أصولك وتكتب ملفات جديدة مغير حجمها، تاركة الأصول سليمة على جهازك. ويمكنك إعادة تشغيل الدفعة نفسها بإعدادات مختلفة دون إعادة الرفع."},{"question":"هل يمكنني استخدام إعدادات مختلفة لصور مختلفة في الدفعة نفسها؟","answer":"لا، الدفعة الواحدة تستخدم استراتيجية واحدة ومجموعة إعدادات واحدة لكل صورة في القائمة. وإذا احتاجت بعض الصور معاملة مختلفة، شغّلها كدفعة منفصلة، أو أزل الزائدة بأيقونة سلة المهملات في بطاقتها."},{"question":"ماذا أفعل إذا بدت صورة ضبابية بعد تغيير حجمها جمليًا؟","answer":"راجع أولًا هل كُبّرت صورة صغيرة: تأكد من تفعيل خيار عدم تكبير الصور الأصغر وأعد تشغيل الدفعة. ثم راجع إعداد الجودة، لأن جودة منخفضة جدًا تنعّم التفاصيل."}];
